  &DefaultButton;




function dir$sysrightunit(p){
  this.constructor(p);
}
dir$sysrightunit.prototype = new DirEvent();
dir$sysrightunit.prototype.beforeInit = function(){
  var p = this._dir;
  if (p.options.action == 'EDIT') {
    p.field('username').disabled = true;
  }
}
dir$sysrightunit.prototype.afterInit = function(){
  var p = this._dir;
  p.options.dataChanged = true;
}
dir$sysrightunit.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    default:
      break;
  }
}
dir$sysrightunit.prototype.gridCellValueChange = function (o, g, r, c, v) {
  var p = this._dir;
  switch (c){
    case 'ma_unit':
      p.grequest(g, 'Unit', '', ['ma_unit'], null, r);
      break;
    default:
      break;
  }
}








select isnull(max(unit_id), 0) as [#unit_id] from sysunit where ma_unit = @ma_unit






select @@fields into #@@table from @@table a where [%whereFieldKey]
[%updateRef]
select * from #@@table
drop table #@@table
if @action <> 'NEW' select username, nickname from vsysuserinfo where user_id = @user_id







if exists(select 1 from @sysrightunit2 group by unit_id having count(*) > 1) begin
  select '$unitDuplicate' as pauseToast
  return
end
select @user_id = user_id, @status = 1 from vsysuserinfo where username = @username







delete sysrightunit2 where [%whereFieldKey]
exec ISWIFTStoredUpdateRightUnit @user_id, @@userId, @@admin







if exists(select 1 from @@table where [%whereFieldKeyOld]) begin
  select '$codeExistsNewMsg' as message, 'username' as field
  return
end







update @@table set user_id = @user_id where user_id = @@old_user_id
update @@table set datetime2 = getdate(), user_id2 = @@userId where [%whereFieldKey]

delete sysrightunit2 where user_id = @@old_user_id







if exists(select 1 from @@table a where [%whereFieldKey]) begin
  select '$codeExistsNewMsg' as message, 'username' as field
  return
end
select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId







if exists(select 1 from @sysrightunit2 where a_view = 1 or a_new = 1 or a_edit = 1 or a_del = 1) begin
	insert into sysrightunit2 select @user_id, line, unit_id, a_view, a_new, a_edit, a_del from @sysrightunit2 
end
exec ISWIFTStoredUpdateRightUnit @user_id, @@userId, @@admin
select '' as message, is_user as [#is_user], @user_id as [#user_id] from vsysuserinfo where username = @username
